"""Generate the native definitions from the same catalog used by the launchers."""
import argparse, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def render():
    data = json.loads((ROOT / 'Achievements/earthbound.json').read_text(encoding='utf-8'))
    rows = data['achievements']
    if data['schema'] != 1 or data['gameId'] != 'earthbound' or not 1 <= len(rows) <= 64:
        raise ValueError('Invalid catalog')
    ids = set()
    lines = ['/* SPDX-License-Identifier: GPL-3.0-or-later',
             ' * Generated by scripts/generate_achievement_catalog.py; edit earthbound.json. */',
             '#ifndef EB_ACHIEVEMENT_CATALOG_H', '#define EB_ACHIEVEMENT_CATALOG_H',
             'static const ca_definition definitions[] = {']
    quote = lambda value: json.dumps(value, ensure_ascii=True)
    for row in rows:
        if row['id'] in ids or row['rule'] not in ('counter','milestone') or row['target'] < 1:
            raise ValueError('Duplicate or invalid achievement')
        ids.add(row['id'])
        # Popup titles must stay within the smallest supported native crop.
        if len(row['title']) > 28 or any(ord(ch) > 126 for ch in row['title']):
            raise ValueError('Unsupported popup title')
        values = ', '.join(quote(row[field]) for field in ('id','title','description','event'))
        lines.append(f' {{{values}, {row["target"]}, CA_{row["rule"].upper()}}},')
    lines += ['};', 'typedef struct { uint16_t flag; const char *event; } achievement_flag_rule;',
              'static const achievement_flag_rule flag_rules[] = {']
    for row in rows:
        if 'flag' in row:
            if not 0 < row['flag'] <= 2048: raise ValueError('Invalid flag')
            lines.append(f' {{{row["flag"]}, {quote(row["event"])}}},')
    lines += ['};', 'typedef struct { uint16_t enemy; const char *event; } achievement_enemy_rule;',
              'static const achievement_enemy_rule enemy_rules[] = {']
    for row in rows:
        for enemy in row.get('enemies', []):
            lines.append(f' {{{enemy}, {quote(row["event"])}}},')
    lines += ['};', '#endif', '']
    return '\n'.join(lines)

if __name__ == '__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args=parser.parse_args()
    path=ROOT/'Achievements/earthbound_catalog.h'
    generated=render()
    document=ROOT/'docs/ACHIEVEMENTS.md'
    marker='<!-- achievement-set -->'
    rows=json.loads((ROOT/'Achievements/earthbound.json').read_text(encoding='utf-8'))['achievements']
    table='\n\n| Category | Achievement | Goal |\n|---|---|---|\n'+'\n'.join(f'| {r["category"]} | {r["title"]} | {r["description"]} |' for r in rows)+'\n'
    contents=document.read_text(encoding='utf-8')
    desired=contents[:contents.index(marker)+len(marker)]+table
    if args.check:
        if path.read_text(encoding='utf-8') != generated: raise SystemExit('Catalog header is stale')
        if contents != desired: raise SystemExit('Achievement guide is stale')
        print('Achievement catalog: synchronized')
    else:
        path.write_text(generated, encoding='utf-8', newline='\n')
        document.write_text(desired, encoding='utf-8', newline='\n')
